let accidentStep=0;
function currentAccident(){return (db.accidents||[]).find(x=>x.id===accidentId)}
function newAccident(){const a={id:uid(),companyId:state.company,created:new Date().toISOString(),status:'Rozpracované'};(db.accidents??=[]).push(a);save();accidentId=a.id;accidentStep=0;go('accident')}
function openAccident(id){const x=(db.accidents||[]).find(a=>a.id===id);if(x)state.company=x.companyId;accidentId=id;accidentStep=0;go('accident')}
function deleteAccident(id){const a=(db.accidents||[]).find(x=>x.id===id);if(!a)return;const desc=(a.employee||'Bez mena')+' · '+(a.date||'bez dátumu');if(!window.confirm('Naozaj natrvalo vymazať pracovný úraz: '+desc+'?\n\nÚdaje tohto spisu sa odstránia z evidencie. Ostatné audity a firmy ostanú zachované.'))return;db.accidents=db.accidents.filter(x=>x.id!==id);save();if(accidentId===id)accidentId=null;go('accidents');}

const RPU_MAX_DIGITS = Object.freeze({"accidentNumber":11,"ico":8,"occupationCode":7,"age":2,"gender":1,"organizationSize":1,"citizenshipCode":1,"workplaceSpec":1,"workplaceCode":3,"injuryCode":3,"bodyCode":2,"processCode":2,"activityCode":2,"deviationCode":2,"contactCode":2,"materialActivity":8,"materialDeviation":8,"materialContact":8,"employmentCode":3,"pnDays":3});
function accidentNumericClean(key,value){
 const limit=RPU_MAX_DIGITS[key];
 return limit ? String(value??'').replace(/\D/g,'').slice(0,limit) : value;
}
function accidentSet(k,v){const a=currentAccident();if(!a)return;a[k]=accidentNumericClean(k,v);a.updated=new Date().toISOString();save()}
function accidentLimitedInput(el,key){
 const cleaned=accidentNumericClean(key,el.value);
 if(cleaned!==el.value)el.value=cleaned;
 accidentSet(key,cleaned);
}

function accidentNext(n){accidentStep=Math.max(0,Math.min(accidentSections.length-1,accidentStep+n));render();window.scrollTo(0,0)}
