function accidentChooseCode(key,code){const a=currentAccident();if(!a)return;accidentSet(key,code);if(key==='sourceCode'||key==='causeCode'){const detailKey=key==='sourceCode'?'source':'cause';const label=accidentCodeLabel(key,code);accidentSet(detailKey,label);const detailInput=document.getElementById('ai_'+detailKey);if(detailInput)detailInput.value=label;}const el=document.getElementById('ai_'+key);if(el)el.value=code;const panel=document.getElementById('acpicker_'+key);if(panel)panel.hidden=true;const summary=document.getElementById('acsummary_'+key);if(summary)summary.textContent=accidentCodeLabel(key,code)}
function accidentCodeLabel(key,code){return (accidentCodeLists[key]||[]).find(x=>x.code===code)?.label||''}
function accidentCodeSearch(key,term){const box=document.getElementById('acresults_'+key);if(!box)return;const query=term.toLocaleLowerCase('sk').trim();const list=(accidentCodeLists[key]||[]).filter(x=>(x.code+' '+x.label).toLocaleLowerCase('sk').includes(query)).slice(0,60);box.innerHTML=list.map(x=>'<button type="button" class="ac-option" onclick="accidentChooseCode(\''+key+'\',\''+x.code+'\')"><b>'+esc(x.code)+'</b> '+esc(x.label)+'</button>').join('')||'<div class="muted smalltext" style="padding:12px">Žiadny výsledok</div>'}
function accidentTogglePicker(key){const el=document.getElementById('acpicker_'+key);if(!el)return;el.hidden=!el.hidden;if(!el.hidden){accidentCodeSearch(key,'');document.getElementById('acsearch_'+key)?.focus()}}
function accidentField(key,label,type){const a=currentAccident()||{},value=esc(a[key]||'');let control=type==='textarea'?'<textarea id="ai_'+key+'" oninput="accidentSet(\''+key+'\',this.value)">'+value+'</textarea>':(RPU_MAX_DIGITS[key]?'<input id="ai_'+key+'" type="text" inputmode="numeric" pattern="[0-9]*" maxlength="'+RPU_MAX_DIGITS[key]+'" title="Najviac '+RPU_MAX_DIGITS[key]+' číslic podľa políčok RPU" value="'+esc(accidentNumericClean(key,a[key]||''))+'" oninput="accidentLimitedInput(this,\''+key+'\')">':'<input id="ai_'+key+'" type="'+(type||'text')+'" value="'+value+'" oninput="accidentSet(\''+key+'\',this.value)">');if(accidentCodeLists[key]){const a=currentAccident()||{};const code=String(a[key]||'');return '<div class="field"><label for="ai_'+key+'">'+esc(label)+'</label><div class="ac-code-row"><input id="ai_'+key+'" value="'+esc(code)+'" readonly placeholder="Vyber kód z číselníka"><button type="button" class="btn secondary small" onclick="accidentTogglePicker(\''+key+'\')">🔎 Hľadať</button></div><div id="acsummary_'+key+'" class="smalltext muted" style="margin-top:5px">'+esc(accidentCodeLabel(key,code))+'</div><div id="acpicker_'+key+'" class="ac-picker" hidden><input id="acsearch_'+key+'" class="search" placeholder="Zadaj názov alebo kód..." oninput="accidentCodeSearch(\''+key+'\',this.value)"><div id="acresults_'+key+'" class="ac-results"></div></div></div>'}return '<div class="field"><label for="ai_'+key+'">'+esc(label)+'</label>'+control+'</div>'}
function renderAccidentForm(){const a=currentAccident();if(!a)return '<div class="empty">Záznam sa nenašiel.</div>';const sec=accidentSections[accidentStep];let fields=sec[1].map(x=>accidentField(...x)).join('');return '<div class="eyebrow">'+esc(company()?.name||'')+' / Pracovný úraz</div><div class="row" style="flex-wrap:wrap"><div class="title">Vyšetrovací hárok</div><button type="button" class="btn small danger" onclick="deleteAccident(accidentId)">🗑 Vymazať tento úraz</button></div><div class="muted">'+esc(a.employee||'Nový záznam')+' · priebežné ukladanie · krok '+(accidentStep+1)+' z '+accidentSections.length+'</div><div class="progress"><div style="width:'+((accidentStep+1)/accidentSections.length*100)+'%"></div></div><div class="panel"><h3>'+esc(sec[0])+'</h3><div class="accident-fields">'+fields+'</div><div class="actions"><button class="btn secondary" onclick="'+(accidentStep?'accidentNext(-1)':'go(\'accidents\')')+'">← '+(accidentStep?'Späť':'Zoznam úrazov')+'</button>'+(accidentStep<2?'<button class="btn" onclick="accidentNext(1)">Ďalej →</button>':'')+'</div></div><div class="warning">Pracovná verzia modulu. Vyhľadávanie vybraných kódov ESAW je dostupné podľa priloženej vyhlášky č. 500/2006 Z. z. Kódy zdroja a príčiny úrazu sa vyberajú z číselníkov modulov 7 a 8 vyhlášky č. 500/2006 Z. z.; slovný opis môžeš ďalej spresniť podľa konkrétneho úrazu. Originálne tlačivá sú dostupné nižšie v testovacej verzii. Pred použitím over údaje a podpisy. Pred odoslaním skontroluj údaje a zabezpeč podpisy.</div>'}
