 const must=[['employee','Meno poškodeného'],['date','Dátum úrazu'],['time','Čas úrazu'],['place','Miesto úrazu'],['position','Pracovné zaradenie'],['description','Opis úrazu'],['source','Zdroj úrazu'],['cause','Príčina úrazu'],['injuryCode','Kód druhu poranenia'],['bodyCode','Kód poranenej časti tela'],['representative','Zástupca zamestnávateľa']];
